import{_ as t,a,b as n}from"./chunks/setup-smartscreen-2.Bm2h4sAv.js";import{_ as i,a as o}from"./chunks/setup-vrchat-osc.OjexboPL.js";import{_ as r,o as s,c as l,ag as h}from"./chunks/framework.DTisvaUJ.js";const C=JSON.parse('{"title":"Getting started — Speech recognition and synthesis in VRChat","description":"Install Mutelink and prepare for conversations in VRChat. Set up VB-Audio Virtual Cable, VRChat microphone and OSC settings, and Quick Setup.","frontmatter":{"title":"Getting started — Speech recognition and synthesis in VRChat","description":"Install Mutelink and prepare for conversations in VRChat. Set up VB-Audio Virtual Cable, VRChat microphone and OSC settings, and Quick Setup.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/getting-started"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Getting started — Speech recognition and synthesis in VRChat | Mutelink"}],["meta",{"property":"og:description","content":"Install Mutelink and prepare for conversations in VRChat. Set up VB-Audio Virtual Cable, VRChat microphone and OSC settings, and Quick Setup."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/guide/getting-started"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Getting started — Speech recognition and synthesis in VRChat | Mutelink"}],["meta",{"name":"twitter:description","content":"Install Mutelink and prepare for conversations in VRChat. Set up VB-Audio Virtual Cable, VRChat microphone and OSC settings, and Quick Setup."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}]]},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"en/guide/getting-started.md"}'),u={name:"en/guide/getting-started.md"};function p(c,e,d,g,m,k){return s(),l("div",null,[...e[0]||(e[0]=[h('<h1 id="はじめかた" tabindex="-1">Getting started <a class="header-anchor" href="#はじめかた" aria-label="Permalink to &quot;Getting started {#はじめかた}&quot;">​</a></h1><p>Follow these steps from installation to talking in VRChat. Quick Setup guides you through settings inside Mutelink; this page focuses on preparation outside the app.</p><h2 id="_1-vb-audio-virtual-cableを入れる" tabindex="-1">1. Install VB-Audio Virtual Cable <a class="header-anchor" href="#_1-vb-audio-virtual-cableを入れる" aria-label="Permalink to &quot;1. Install VB-Audio Virtual Cable {#_1-vb-audio-virtual-cableを入れる}&quot;">​</a></h2><p>This free software routes synthesized speech to the VRChat microphone. Skip this step if you only use the chatbox.</p><ol><li>Download and install <a href="https://vb-audio.com/Cable/" target="_blank" rel="noreferrer">VB-Audio Virtual Cable</a>.</li><li>Check that “CABLE Input” and “CABLE Output” appear in Windows sound settings. Restart your PC if they do not.</li></ol><p><strong>Install it before Mutelink.</strong> If you installed it while Mutelink was open, restart Mutelink.</p><p><img src="'+t+'" alt="CABLE Input and CABLE Output in Windows sound settings"></p><h2 id="_2-mutelinkをインストールする" tabindex="-1">2. Install Mutelink <a class="header-anchor" href="#_2-mutelinkをインストールする" aria-label="Permalink to &quot;2. Install Mutelink {#_2-mutelinkをインストールする}&quot;">​</a></h2><ol><li>Download the installer (<code>Mutelink_x.x.x_x64-setup.exe</code>) from <a href="https://github.com/utyujinn/Mutelink-releases/releases" target="_blank" rel="noreferrer">Releases</a> or <a href="https://utyujin.booth.pm/items/8914909" target="_blank" rel="noreferrer">BOOTH</a>.</li><li>Run it. Administrator privileges are not required.</li></ol><p>The app is not code-signed, so Windows may display “Windows protected your PC.” Click “More info” and then “Run anyway.”</p><table tabindex="0"><thead><tr><th>① Click “More info”</th><th>② Click “Run anyway”</th></tr></thead><tbody><tr><td><img src="'+a+'" alt="Click More info"></td><td><img src="'+n+'" alt="Click Run anyway"></td></tr></tbody></table><h2 id="_3-クイックセットアップを進める" tabindex="-1">3. Complete Quick Setup <a class="header-anchor" href="#_3-クイックセットアップを進める" aria-label="Permalink to &quot;3. Complete Quick Setup {#_3-クイックセットアップを進める}&quot;">​</a></h2><p>Quick Setup opens on first launch. Choose how you want to use the app: speaking, translation, typing, reading others’ speech as captions, or VR. Only the relevant settings are shown.</p><p>Pay particular attention to these three settings.</p><ul><li><strong>Microphone</strong>: select the microphone you speak into. Do not select “CABLE Output,” or the app will recognize its own synthesized speech.</li><li><strong>Speakers</strong>: for speech synthesis, select both “CABLE Input” to send audio to VRChat and your own speakers or headphones for monitoring.</li><li><strong>Recognition engine and voice</strong>: if unsure, see <a href="/Mutelink-releases/en/compare/speech-recognition">speech recognition engines</a> and <a href="/Mutelink-releases/en/compare/voices">voice samples</a>. You can change them later.</li></ul><p>Run Quick Setup again from Settings &gt; Usage.</p><h2 id="_4-vrchat側を設定する" tabindex="-1">4. Configure VRChat <a class="header-anchor" href="#_4-vrchat側を設定する" aria-label="Permalink to &quot;4. Configure VRChat {#_4-vrchat側を設定する}&quot;">​</a></h2><h3 id="声を流すとき" tabindex="-1">For voice output <a class="header-anchor" href="#声を流すとき" aria-label="Permalink to &quot;For voice output {#声を流すとき}&quot;">​</a></h3><p>In VRChat Settings &gt; Audio, select “CABLE Output” as the microphone.</p><div class="warning custom-block"><p class="custom-block-title">Do not leave the microphone on “Default”</p><p>With “Default,” VRChat may use your physical microphone and share your own voice. Always select “CABLE Output.”</p></div><p>Keep the VRChat microphone toggled on so synthesized speech is not cut off.</p><p><img src="'+i+'" alt="Select CABLE Output as the VRChat microphone"></p><h3 id="チャットボックスだけで使うとき" tabindex="-1">For chatbox-only use <a class="header-anchor" href="#チャットボックスだけで使うとき" aria-label="Permalink to &quot;For chatbox-only use {#チャットボックスだけで使うとき}&quot;">​</a></h3><p>Mute your VRChat microphone. Otherwise, others can hear the voice you use for speech recognition directly.</p><h3 id="チャットボックスを使うとき" tabindex="-1">For chatbox messages <a class="header-anchor" href="#チャットボックスを使うとき" aria-label="Permalink to &quot;For chatbox messages {#チャットボックスを使うとき}&quot;">​</a></h3><p>Enable OSC in VRChat (Action Menu &gt; Options &gt; OSC &gt; Enabled).</p><p><img src="'+o+'" alt="Enable OSC in VRChat"></p><h2 id="_5-使ってみる" tabindex="-1">5. Try it <a class="header-anchor" href="#_5-使ってみる" aria-label="Permalink to &quot;5. Try it {#_5-使ってみる}&quot;">​</a></h2><p>Enable recognition on the main screen and speak into your microphone. Review the recognized text and send it, or enable automatic sending.</p><p>Press “?” at the top right of settings to see explanations of buttons and settings.</p><p>If something does not work, see <a href="/Mutelink-releases/en/help/troubleshooting">Troubleshooting</a>.</p>',31)])])}const _=r(u,[["render",p]]);export{C as __pageData,_ as default};
